    pub(super) fn private_release_receipt(&self) -> (usize, usize, usize, usize) {
        (
            self.chunks.len(),
            self.chunks.capacity(),
            self.payload_chunks(),
            self.chunks
                .iter()
                .filter_map(|chunk| chunk.values.as_ref())
                .map(|values| values.iter().filter(|value| value.is_some()).count())
                .sum(),
        )
    }
